  async saveFact(mdl): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(
          `${environment.cloudUrl}${environment.coreservice}/fact/insertfact`,
          mdl
        )
      );
      if (res && res.msg == 1) {
        // this.tost.openSnackBar(res.value, '');
        return res;
      } else {
        // this.tost.openSnackBar(res.value, 'E');
        return res;
      }
    } catch (err) {
      this.tost.openSnackBar(`Fact creation failed ${err}`, 'E');
      return { msg: -1, error: err, value: '' };
    }
  }

