  // QUICK FACT ADD

  async lastID(selectedIssues: any): Promise<number> {
    // Highlight colour follows the LAST issue the user clicked in the
    // QFact panel (selectionActions.qfactSelected appends in click
    // order). Spec: "the last color we selected is the preferable
    // colour for the highlight, in both transcript and PDF". The
    // previous getcolorid round-trip picked the server-ranked first row,
    // which produced the FIRST-selected issue's colour — wrong order.
    if (!selectedIssues?.length) return 0;
    selectedIssues.map((a) => (a.nIid = a.nIid || a.nIssueid));
    return selectedIssues[selectedIssues.length - 1]?.nIid || 0;
  }

  async submitQuickFact(
    selectedIssues: any,
    docInfo,
    jTexts: any,
    tempAnnots: any,
    isNoteEdited?: boolean,
    jLinktype?: any,
    jContacts?: any
  ): Promise<any> {
    const colorid = await this.lastID(selectedIssues);
    const finalMDL = {
      nBDid: docInfo.nBundledetailid,
      jAn: JSON.stringify(tempAnnots.map((a) => a.annots)),
      nColorid: colorid,
      jT: JSON.stringify(jTexts.filter((a) => a)),
      jOT: JSON.stringify(tempAnnots.map((a) => a.text).filter((a) => a)),
      jIssues: JSON.stringify(
        selectedIssues.map((a) => [
          a.nIid,
          a.nImpactid ? a.nImpactid : 0,
          a.nRelid ? a.nRelid : 0,
        ])
      ),
      jLinktype: jLinktype,
      cFtype: 'QF',
      cIsNote: isNoteEdited ? 'Y' : 'N',
    };

    if (jContacts?.length) {
      finalMDL['jContacts'] = jContacts;
    }
    const res = await this.saveQuickFact(finalMDL);
    return { res, colorid };
  }

