  async getPermissions(
    nFactid: string,
    userIds: string[]
  ): Promise<UserPermission[]> {
    try {
      const res: any = await firstValueFrom(
        this.http.get<any>(
          `${environment.cloudUrl2}${environment.realtimeserive}/fact/permissions/${nFactid}`,
          { params: { userIds: userIds.join(',') } }
        )
      );

      if (res && res.msg === 1) {
        return res.value; // should be array of { nUserid, canEdit, canReshare, canComment }
      } else {
        this.tost.openSnackBar(
          res?.value || 'Failed to fetch permissions',
          'E'
        );
        return [];
      }
    } catch (err) {
      this.tost.openSnackBar(`Permission fetch failed: ${err}`, 'E');
      return [];
    }
  }
